# =============================================================================
#  JEDNO POLECENIE - pobiera, sprawdza, robi raport, pyta o sprzatanie.
#  Wklej cala zawartosc tego pliku do PowerShell jako JEDNA linie i Enter.
#  (Plik jest tylko zrodlem tej jednej linii - agent go nie potrzebuje.)
# =============================================================================
$ErrorActionPreference='Stop'; $ProgressPreference='SilentlyContinue'; [Net.ServicePointManager]::SecurityProtocol=[Net.SecurityProtocolType]::Tls12; [Console]::OutputEncoding=[Text.Encoding]::UTF8; $env:PYTHONIOENCODING='utf-8'; & { $u='https://github.com/zielinski25/Sterownik-Pieca-C.O./archive/refs/heads/arena/a6b30642-sterownik-pieca-c-o.zip'; $z="$HOME\Desktop\sprzatanie.zip"; $d="$HOME\Desktop\SprzatanieAgenta"; Write-Host "`n[1/4] Pobieram agenta..." -ForegroundColor Cyan; $ok=$false; for($i=1;$i -le 3 -and -not $ok;$i++){ try{ Invoke-WebRequest -Uri $u -OutFile $z -UseBasicParsing; $ok=$true } catch { Write-Host "  proba $i nieudana: $($_.Exception.Message)" -ForegroundColor Yellow; Start-Sleep 2 } }; if(-not $ok){ Write-Host "`nPobranie nie wyszlo. Otworz recznie w przegladarce:`n$u`n" -ForegroundColor Red; return }; Write-Host "[2/4] Rozpakowuje..." -ForegroundColor Cyan; if(Test-Path $d){ Remove-Item $d -Recurse -Force }; Expand-Archive $z -DestinationPath $d -Force; $a=Get-ChildItem $d -Recurse -Filter agent.py | Select-Object -First 1; if(-not $a){ Write-Host "W archiwum nie ma agent.py - przerywam." -ForegroundColor Red; return }; Set-Location $a.DirectoryName; Write-Host "[3/4] Sprawdzam Pythona..." -ForegroundColor Cyan; $py=$null; foreach($k in @('python','py')){ try{ & $k -c "import sys" 2>$null; if($LASTEXITCODE -eq 0){ $v=(& $k -c "import sys;print(sys.version_info[1])" 2>$null); if([int]$v -ge 9){ $py=$k; break } } } catch {} }; if(-not $py){ Write-Host "  Brak Pythona 3.9+. Probuje winget..." -ForegroundColor Yellow; try{ winget install --id Python.Python.3.12 --silent --accept-package-agreements --accept-source-agreements }catch{ Write-Host "  winget niedostepny - zainstaluj Pythona z python.org" -ForegroundColor Red; return }; $env:Path=[Environment]::GetEnvironmentVariable("Path","Machine")+";"+[Environment]::GetEnvironmentVariable("Path","User"); $py='python' }; Write-Host "  Python: $py" -ForegroundColor Green; Write-Host "[4/4] Skanuje dysk (tylko czyta, nic nie rusza)..." -ForegroundColor Cyan; & $py agent.py --tylko-raport; Write-Host "`nFolder agenta: $($a.DirectoryName)" -ForegroundColor Green; if((Read-Host "`nUruchomic teraz sprzatanie? Najpierw pokaze liste i zapyta o zgode [t/N]") -match '^(t|tak|y)$'){ & $py agent.py --bez-ai } else { Write-Host "OK, nic nie zmienione. Raporty: $env:LOCALAPPDATA\SprzatanieDysku\raporty" -ForegroundColor Gray } }
